#include <errno.h>
#include <inttypes.h>
#include <libusb.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

#define NVIDIA_VID 0x0955
#define T234_RCM_PID 0x7423
#define USB_TIMEOUT_MS 5000
#define POLL_BL_TIMEOUT_MS 30000
#define WRITE_CHUNK_SIZE 0x4000
#define BR_UID_DESCRIPTOR_SIZE 0x82
#define BL_BANNER_SIZE 0x44

struct usb_session {
    libusb_device_handle *handle;
    int interface_number;
    unsigned char bulk_in;
    unsigned char bulk_out;
    bool claimed;
};

struct artifact {
    const char *kind;
    const char *name;
};

static const struct artifact bootrom_artifacts[] = {
    {"bct_br", "br_bct_BR.bct"},
    {"mb1", "mb1_t234_prod_aligned_sigheader.bin.encrypt"},
    {"psc_bl1", "psc_bl1_t234_prod_aligned_sigheader.bin.encrypt"},
    {"bct_mb1", "mb1_bct_MB1_sigheader.bct.encrypt"},
};

static const struct artifact bootloader_artifacts[] = {
    {"bct_mem", "mem_rcm_sigheader.bct.encrypt"},
    {"blob", "blob.bin"},
};

static void usage(FILE *stream, const char *program)
{
    fprintf(stream,
            "Usage:\n"
            "  %s probe\n"
            "  %s verify ARTIFACT_DIR\n"
            "  %s boot ARTIFACT_DIR\n\n"
            "The boot command performs a volatile T234 RCM boot. It does not write\n"
            "QSPI or attached storage. ARTIFACT_DIR must contain the presigned files\n"
            "generated by NVIDIA Jetson Linux R35 tegraflash.\n",
            program, program, program);
}

static int64_t monotonic_milliseconds(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

static void close_session(struct usb_session *session)
{
    if (session->handle == NULL) {
        return;
    }
    if (session->claimed) {
        libusb_release_interface(session->handle, session->interface_number);
    }
    libusb_close(session->handle);
    memset(session, 0, sizeof(*session));
    session->interface_number = -1;
}

static int find_bulk_interface(libusb_device *device, struct usb_session *session)
{
    struct libusb_config_descriptor *config = NULL;
    int rc = libusb_get_active_config_descriptor(device, &config);

    if (rc != LIBUSB_SUCCESS) {
        fprintf(stderr, "Cannot read active USB configuration: %s\n",
                libusb_error_name(rc));
        return rc;
    }

    rc = LIBUSB_ERROR_NOT_FOUND;
    for (uint8_t i = 0; i < config->bNumInterfaces; ++i) {
        const struct libusb_interface *interface = &config->interface[i];

        for (int a = 0; a < interface->num_altsetting; ++a) {
            const struct libusb_interface_descriptor *alt = &interface->altsetting[a];
            unsigned char bulk_in = 0;
            unsigned char bulk_out = 0;

            for (uint8_t e = 0; e < alt->bNumEndpoints; ++e) {
                const struct libusb_endpoint_descriptor *endpoint = &alt->endpoint[e];

                if ((endpoint->bmAttributes & LIBUSB_TRANSFER_TYPE_MASK) !=
                    LIBUSB_TRANSFER_TYPE_BULK) {
                    continue;
                }
                if ((endpoint->bEndpointAddress & LIBUSB_ENDPOINT_DIR_MASK) ==
                    LIBUSB_ENDPOINT_IN) {
                    bulk_in = endpoint->bEndpointAddress;
                } else {
                    bulk_out = endpoint->bEndpointAddress;
                }
            }

            if (bulk_in != 0 && bulk_out != 0) {
                session->interface_number = alt->bInterfaceNumber;
                session->bulk_in = bulk_in;
                session->bulk_out = bulk_out;
                rc = LIBUSB_SUCCESS;
                goto done;
            }
        }
    }

done:
    libusb_free_config_descriptor(config);
    return rc;
}

static int open_t234_rcm(libusb_context *context, int wait_ms,
                         struct usb_session *session)
{
    int64_t deadline = monotonic_milliseconds() + wait_ms;
    int last_error = LIBUSB_ERROR_NO_DEVICE;

    memset(session, 0, sizeof(*session));
    session->interface_number = -1;

    do {
        libusb_device **devices = NULL;
        ssize_t count = libusb_get_device_list(context, &devices);
        libusb_device *match = NULL;
        unsigned matches = 0;

        if (count < 0) {
            return (int)count;
        }

        for (ssize_t i = 0; i < count; ++i) {
            struct libusb_device_descriptor descriptor;

            if (libusb_get_device_descriptor(devices[i], &descriptor) !=
                LIBUSB_SUCCESS) {
                continue;
            }
            if (descriptor.idVendor == NVIDIA_VID &&
                descriptor.idProduct == T234_RCM_PID) {
                match = devices[i];
                ++matches;
            }
        }

        if (matches > 1) {
            fprintf(stderr, "Found %u NVIDIA T234 recovery devices; expected one.\n",
                    matches);
            libusb_free_device_list(devices, 1);
            return LIBUSB_ERROR_BUSY;
        }

        if (matches == 1) {
            last_error = libusb_open(match, &session->handle);
            if (last_error == LIBUSB_SUCCESS) {
                last_error = find_bulk_interface(match, session);
            }
            if (last_error == LIBUSB_SUCCESS) {
                int active = libusb_kernel_driver_active(
                    session->handle, session->interface_number);

                if (active == 1) {
                    last_error = libusb_detach_kernel_driver(
                        session->handle, session->interface_number);
                } else {
                    /* Darwin commonly cannot answer this query. Claiming the
                     * interface is the authoritative availability check. */
                    last_error = LIBUSB_SUCCESS;
                }
            }
            if (last_error == LIBUSB_SUCCESS) {
                last_error = libusb_claim_interface(
                    session->handle, session->interface_number);
                session->claimed = last_error == LIBUSB_SUCCESS;
            }
        }

        libusb_free_device_list(devices, 1);
        if (last_error == LIBUSB_SUCCESS) {
            return LIBUSB_SUCCESS;
        }

        close_session(session);
        if (monotonic_milliseconds() >= deadline) {
            break;
        }
        usleep(100000);
    } while (true);

    return last_error;
}

static void print_usb_error(const char *operation, int rc)
{
    fprintf(stderr, "%s: %s (%d)\n", operation, libusb_error_name(rc), rc);
}

static int read_bootrom_uid(struct usb_session *session)
{
    unsigned char descriptor[BR_UID_DESCRIPTOR_SIZE] = {0};
    int rc = libusb_control_transfer(
        session->handle,
        LIBUSB_ENDPOINT_IN | LIBUSB_REQUEST_TYPE_STANDARD |
            LIBUSB_RECIPIENT_DEVICE,
        LIBUSB_REQUEST_GET_DESCRIPTOR,
        (LIBUSB_DT_STRING << 8) | 3,
        0,
        descriptor,
        sizeof(descriptor),
        USB_TIMEOUT_MS);

    if (rc < 0) {
        print_usb_error("BootROM UID descriptor read failed", rc);
        return rc;
    }
    if (rc < 2 || descriptor[1] != LIBUSB_DT_STRING || descriptor[0] < 2) {
        fprintf(stderr, "BootROM returned an invalid UID descriptor (%d bytes).\n", rc);
        return LIBUSB_ERROR_IO;
    }

    unsigned length = descriptor[0] < rc ? descriptor[0] : (unsigned)rc;
    printf("BR_CID: 0x");
    for (unsigned i = 2; i + 1 < length; i += 2) {
        unsigned char low = descriptor[i];
        unsigned char high = descriptor[i + 1];

        if (high == 0 && low >= 0x20 && low <= 0x7e) {
            putchar(low);
        } else {
            printf("%02x%02x", high, low);
        }
    }
    putchar('\n');
    return LIBUSB_SUCCESS;
}

static int join_path(char *destination, size_t capacity, const char *directory,
                     const char *name)
{
    int written = snprintf(destination, capacity, "%s/%s", directory, name);

    if (written < 0 || (size_t)written >= capacity) {
        fprintf(stderr, "Artifact path is too long: %s/%s\n", directory, name);
        return -1;
    }
    return 0;
}

static int validate_artifacts(const char *directory, bool verbose)
{
    const struct artifact *sets[] = {bootrom_artifacts, bootloader_artifacts};
    const size_t counts[] = {
        sizeof(bootrom_artifacts) / sizeof(bootrom_artifacts[0]),
        sizeof(bootloader_artifacts) / sizeof(bootloader_artifacts[0]),
    };
    char path[4096];

    for (size_t set = 0; set < sizeof(sets) / sizeof(sets[0]); ++set) {
        for (size_t i = 0; i < counts[set]; ++i) {
            struct stat metadata;

            if (join_path(path, sizeof(path), directory, sets[set][i].name) != 0) {
                return -1;
            }
            if (stat(path, &metadata) != 0) {
                fprintf(stderr, "Missing artifact %s: %s\n", path, strerror(errno));
                return -1;
            }
            if (!S_ISREG(metadata.st_mode) || metadata.st_size <= 0) {
                fprintf(stderr, "Artifact is not a non-empty regular file: %s\n", path);
                return -1;
            }
            if (verbose) {
                printf("%-8s %10" PRIu64 "  %s\n", sets[set][i].kind,
                       (uint64_t)metadata.st_size, path);
            }
        }
    }
    return 0;
}

static int write_file(struct usb_session *session, const char *kind,
                      const char *path)
{
    unsigned char buffer[WRITE_CHUNK_SIZE];
    FILE *file = fopen(path, "rb");
    struct stat metadata;
    uint64_t sent = 0;

    if (file == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fstat(fileno(file), &metadata) != 0) {
        fprintf(stderr, "Cannot stat %s: %s\n", path, strerror(errno));
        fclose(file);
        return -1;
    }

    printf("Sending %-8s %s (%" PRIu64 " bytes)\n", kind, path,
           (uint64_t)metadata.st_size);
    fflush(stdout);

    while (!feof(file)) {
        size_t count = fread(buffer, 1, sizeof(buffer), file);

        if (count == 0) {
            if (ferror(file)) {
                fprintf(stderr, "Read failed for %s: %s\n", path, strerror(errno));
                fclose(file);
                return -1;
            }
            break;
        }

        size_t offset = 0;
        while (offset < count) {
            int transferred = 0;
            int rc = libusb_bulk_transfer(
                session->handle,
                session->bulk_out,
                buffer + offset,
                (int)(count - offset),
                &transferred,
                USB_TIMEOUT_MS);

            if (rc != LIBUSB_SUCCESS) {
                fprintf(stderr, "USB write failed after %" PRIu64 " bytes of %s: ",
                        sent, path);
                print_usb_error("bulk OUT", rc);
                fclose(file);
                return rc;
            }
            if (transferred <= 0) {
                fprintf(stderr, "USB made no progress while sending %s.\n", path);
                fclose(file);
                return LIBUSB_ERROR_IO;
            }
            offset += (size_t)transferred;
            sent += (uint64_t)transferred;
        }
    }

    fclose(file);
    return LIBUSB_SUCCESS;
}

static int send_artifact_set(struct usb_session *session, const char *directory,
                             const struct artifact *artifacts, size_t count)
{
    char path[4096];

    for (size_t i = 0; i < count; ++i) {
        if (join_path(path, sizeof(path), directory, artifacts[i].name) != 0) {
            return -1;
        }
        int rc = write_file(session, artifacts[i].kind, path);
        if (rc != LIBUSB_SUCCESS) {
            return rc;
        }
    }
    return LIBUSB_SUCCESS;
}

static int read_bootloader_banner(struct usb_session *session)
{
    unsigned char banner[BL_BANNER_SIZE] = {0};
    size_t offset = 0;

    while (offset < sizeof(banner)) {
        int transferred = 0;
        int rc = libusb_bulk_transfer(
            session->handle,
            session->bulk_in,
            banner + offset,
            (int)(sizeof(banner) - offset),
            &transferred,
            POLL_BL_TIMEOUT_MS);

        if (rc != LIBUSB_SUCCESS) {
            print_usb_error("Bootloader banner read failed", rc);
            return rc;
        }
        if (transferred <= 0) {
            fprintf(stderr, "USB made no progress while reading bootloader banner.\n");
            return LIBUSB_ERROR_IO;
        }
        offset += (size_t)transferred;
    }

    char version[65];
    memcpy(version, banner, 64);
    version[64] = '\0';
    for (size_t i = 0; i < 64; ++i) {
        if (version[i] == '\0') {
            break;
        }
        if ((unsigned char)version[i] < 0x20 ||
            (unsigned char)version[i] > 0x7e) {
            version[i] = '.';
        }
    }
    uint32_t last_boot_error =
        (uint32_t)banner[64] |
        ((uint32_t)banner[65] << 8) |
        ((uint32_t)banner[66] << 16) |
        ((uint32_t)banner[67] << 24);

    printf("BL: version %s last_boot_error: %" PRIu32 "\n",
           version, last_boot_error);
    return LIBUSB_SUCCESS;
}

static int probe(libusb_context *context)
{
    struct usb_session session;
    int rc = open_t234_rcm(context, 0, &session);

    if (rc != LIBUSB_SUCCESS) {
        print_usb_error("NVIDIA T234 APX device 0955:7423 not available", rc);
        return 1;
    }

    printf("Found NVIDIA T234 APX 0955:7423\n");
    printf("Interface %d, bulk OUT 0x%02x, bulk IN 0x%02x\n",
           session.interface_number, session.bulk_out, session.bulk_in);
    close_session(&session);
    return 0;
}

static int boot(libusb_context *context, const char *directory)
{
    struct usb_session session;
    int rc;

    if (validate_artifacts(directory, false) != 0) {
        return 1;
    }

    printf("Volatile RCM boot only; QSPI and storage will not be written.\n");
    fflush(stdout);
    rc = open_t234_rcm(context, 0, &session);
    if (rc != LIBUSB_SUCCESS) {
        print_usb_error("Cannot open NVIDIA T234 APX 0955:7423", rc);
        return 1;
    }
    printf("Stage 1: BootROM on interface %d (OUT 0x%02x, IN 0x%02x)\n",
           session.interface_number, session.bulk_out, session.bulk_in);

    rc = read_bootrom_uid(&session);
    if (rc == LIBUSB_SUCCESS) {
        rc = send_artifact_set(
            &session, directory, bootrom_artifacts,
            sizeof(bootrom_artifacts) / sizeof(bootrom_artifacts[0]));
    }
    close_session(&session);
    if (rc != LIBUSB_SUCCESS) {
        return 1;
    }

    printf("Stage 2: waiting for MB1/PSC bootloader handoff...\n");
    rc = open_t234_rcm(context, 30000, &session);
    if (rc != LIBUSB_SUCCESS) {
        print_usb_error("T234 device did not return for bootloader stage", rc);
        return 1;
    }
    rc = read_bootloader_banner(&session);
    close_session(&session);
    if (rc != LIBUSB_SUCCESS) {
        return 1;
    }

    rc = open_t234_rcm(context, 5000, &session);
    if (rc != LIBUSB_SUCCESS) {
        print_usb_error("Cannot reopen T234 bootloader transport", rc);
        return 1;
    }
    rc = send_artifact_set(
        &session, directory, bootloader_artifacts,
        sizeof(bootloader_artifacts) / sizeof(bootloader_artifacts[0]));
    close_session(&session);
    if (rc != LIBUSB_SUCCESS) {
        return 1;
    }

    printf("RCM boot payload sent. The target should now boot from RAM.\n");
    return 0;
}

int main(int argc, char **argv)
{
    libusb_context *context = NULL;
    int rc;
    int result;

    if (argc < 2) {
        usage(stderr, argv[0]);
        return 2;
    }

    rc = libusb_init(&context);
    if (rc != LIBUSB_SUCCESS) {
        print_usb_error("libusb initialization failed", rc);
        return 1;
    }

    if (strcmp(argv[1], "probe") == 0 && argc == 2) {
        result = probe(context);
    } else if (strcmp(argv[1], "verify") == 0 && argc == 3) {
        result = validate_artifacts(argv[2], true) == 0 ? 0 : 1;
    } else if (strcmp(argv[1], "boot") == 0 && argc == 3) {
        result = boot(context, argv[2]);
    } else {
        usage(stderr, argv[0]);
        result = 2;
    }

    libusb_exit(context);
    return result;
}
